	var start = new Date().getTime();
	while (typeof segments == "undefined") {
	    var now = new Date().getTime();
	    if ((now - start) > 3000) {
	    	break;
	    }
	}
    
    <!--For some reason smartpoint treats lists as ; separated strings :(-->
    const airlines = new Set();
	
	const segment_list = segments.split(";");
	
	segment_list.forEach(segment => {
	    airlines.add(segment.slice(0,2));
	});
	
	return Array.from(airlines).join(';');

    
    var start = new Date().getTime();
	while (typeof notepad == "undefined") {
	    var now = new Date().getTime();
	    if ((now - start) > 3000) {
	    	break;
	    }
	}
    
    si_list = new Array();
    
    const notepad_list = notepad.split(';');
    const airlines_list = airlines.split(';');
    
    const ssr_regex = new RegExp("(P\\d+)\/SSRDOCSYYHK1\/(.+)$");
	const ctcm_regex = new RegExp("(P\\d+)\/SSRCTCMYYHK1\/(.+)$");
	const ctce_regex = new RegExp("(P\\d+)\/SSRCTCEYYHK1\/(.+)$");
    
    notepad_list.forEach(entry => {
    	const ssr_regex_match = ssr_regex.exec(entry);
    	const ctcm_regex_match = ctcm_regex.exec(entry);
    	const ctce_regex_match = ctce_regex.exec(entry);
    	if (ssr_regex_match) {
    		airlines_list.forEach(airline => {
    			si_list.push(ssr_regex_match[1] + '/SSRDOCS' + airline + 'HK1/' + ssr_regex_match[2]);
    		});
    	} else if (ctcm_regex_match) {
    		airlines_list.forEach(airline => {
    			si_list.push(ctcm_regex_match[1] + '/SSRCTCM' + airline + 'HK1/' + ctcm_regex_match[2]);
    		});
    	} else if (ctce_regex_match) {
    		airlines_list.forEach(airline => {
    			si_list.push(ctce_regex_match[1] + '/SSRCTCE' + airline + 'HK1/' + ctce_regex_match[2]);
    		});
    	}
    });
    
    return si_list.join(';');

    var start = new Date().getTime();
	while (typeof notepad == "undefined") {
	    var now = new Date().getTime();
	    if ((now - start) > 3000) {
	    	break;
	    }
	}
    
    return notepad.split(';').length;
